from collections import defaultdict

def is_rotationally_symmetric(n, m, edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    def dfs(start, k, visited):
        stack = [(start, k)]
        while stack:
            node, remaining_k = stack.pop()
            if remaining_k == 0:
                return False
            visited.add(node)
            next_node = (node + 1) % n
            if next_node not in visited:
                stack.append((next_node, remaining_k - 1))
            for neighbor in graph[node]:
                if neighbor not in visited:
                    stack.append((neighbor, remaining_k - 1))
        return True

    for k in range(1, n):
        visited = set()
        if not dfs(1, k, visited):
            break
    else:
        return "Yes"
    return "No"

