from collections import defaultdict

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_cycles(n, edges):
    visited = [False] * (n + 1)
    cycles = []

    def dfs(node, parent, current_cycle):
        if visited[node]:
            if node == parent:
                cycles.append(current_cycle[:])
            return True
        visited[node] = True
        current_cycle.append(node)
        for neighbor in graph[node]:
            if dfs(neighbor, node, current_cycle):
                return True
        current_cycle.pop()
        return False

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1, [])

    return cycles

def is_rotationally_symmetric(n, m, edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    cycles = find_cycles(n, edges)

    for cycle in cycles:
        cycle_length = len(cycle)
        if cycle_length > 1:
            g = gcd(n, cycle_length)
            for k in range(1, g):
                rotated_cycle = [(cycle[i] + k) % n for i in range(cycle_length)]
                if sorted(rotated_cycle) != sorted(cycle):
                    return "No"
    return "Yes"

